import { mkdir, readFile, writeFile } from "node:fs/promises";
import { dirname, resolve, sep } from "node:path";

/**
 * Where raw email and attachment bytes live (ADR 0002). The MVP ships the local-disk driver;
 * an S3-compatible driver implements the same interface later.
 */
export interface FileStore {
  /** Stores bytes under a new key. Never overwrites: a key is written once. */
  put(key: string, bytes: Uint8Array): Promise<void>;
  /** Returns the bytes, or null if no file has this key. */
  get(key: string): Promise<Uint8Array | null>;
}

// Keys are generated by the app (`<tenantId>/<uuid>`), never taken from input. The strict
// pattern is a second line of defence against path traversal.
const keyPattern = /^[a-z0-9][a-z0-9_-]*(\/[a-z0-9][a-z0-9_-]*)*$/;

export class InvalidFileKeyError extends Error {
  constructor(key: string) {
    super(`invalid file key: ${JSON.stringify(key)}`);
    this.name = "InvalidFileKeyError";
  }
}

export function createLocalFileStore(rootDir: string): FileStore {
  const root = resolve(rootDir);

  function pathFor(key: string): string {
    if (!keyPattern.test(key)) throw new InvalidFileKeyError(key);
    const path = resolve(root, key);
    if (!path.startsWith(root + sep)) throw new InvalidFileKeyError(key);
    return path;
  }

  return {
    async put(key, bytes) {
      const path = pathFor(key);
      await mkdir(dirname(path), { recursive: true });
      // "wx" fails if the file exists, so a key collision can't overwrite earlier data.
      await writeFile(path, bytes, { flag: "wx" });
    },
    async get(key) {
      const path = pathFor(key);
      try {
        return new Uint8Array(await readFile(path));
      } catch (error) {
        if (error instanceof Error && "code" in error && error.code === "ENOENT") return null;
        throw error;
      }
    },
  };
}

/** In-memory store for tests. */
export function createMemoryFileStore(): FileStore & { files: Map<string, Uint8Array> } {
  const files = new Map<string, Uint8Array>();
  return {
    files,
    async put(key, bytes) {
      if (!keyPattern.test(key)) throw new InvalidFileKeyError(key);
      if (files.has(key)) throw new Error(`file exists: ${key}`);
      files.set(key, bytes);
    },
    async get(key) {
      return files.get(key) ?? null;
    },
  };
}
